              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                const isSelected = selectedTool === type;
                return (
                  <button
                    key={type}
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, type)}
                    onClick={() => onSelectTool(type)}
                    className={`flex flex-col items-center justify-center p-3 rounded border-2 transition-all duration-200 cursor-grab active:cursor-grabbing ${
                      isSelected 
                        ? 'border-blue-500 bg-blue-50' 
                        : 'border-slate-100 bg-white hover:border-slate-300 hover:shadow-sm'
                    }`}
                  >
                    {/* Visual Preview Icon (CSS based) */}
                    <div className="w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-white text-[10px] font-bold text-slate-600 pointer-events-none">
                      {def.label.substring(0,3)}
                    </div>
                    <span className="text-xs font-medium text-slate-700 pointer-events-none">{def.label}</span>
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      <div className="p-4 bg-slate-50 border-t border-slate-200 text-xs text-slate-500">
        <p>Tip: Drag from sidebar to add. Drag ports to wire.</p>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useRef, useEffect, useState } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

interface LogicCanvasProps {
  tool: ComponentType | 'SELECT' | 'WIRE' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number;
  onToolUsed: () => void; // Reset tool after use if needed
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, onToolUsed }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State (Refs for performance to avoid React render loop interference with P5 loop) --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  // -- Interaction State --
  const draggingCompId = useRef<string | null>(null);
  const isDraggingComp = useRef<boolean>(false); // Track if we actually moved the mouse while holding component
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const mousePos = useRef<Point>({ x: 0, y: 0 });

  // -- Simulation Loop --
  useEffect(() => {
    if (!isPlaying) return;

    const interval = setInterval(() => {
      const result = stepSimulation(componentsRef.current, wiresRef.current);
      componentsRef.current = result.components;
      wiresRef.current = result.wires;
    }, tickSpeedMs);

    return () => clearInterval(interval);
  }, [isPlaying, tickSpeedMs]);

  // -- Drag and Drop from Sidebar Handlers --
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-logic-sim') as ComponentType;

    if (type && containerRef.current && COMPONENT_DEFINITIONS[type]) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const def = COMPONENT_DEFINITIONS[type];
      const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
      const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

      const newComp: CircuitComponent = {
        id: crypto.randomUUID(),
        type: type,
        x: snapX,
        y: snapY,
        inputValues: new Array(def.inputs).fill(false),
        outputValues: new Array(def.outputs).fill(false)
      };

      componentsRef.current.push(newComp);
    }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current) return;

    // Dynamic import/usage of p5 (assuming loaded via CDN or npm)
    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    const sketch = (p: p5Types) => {

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(12);
        p.textAlign(p.CENTER, p.CENTER);
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      // -- DRAW LOOP --
      p.draw = () => {
        p.background(COLOR_BG);

        // Draw Grid
        p.stroke(COLOR_GRID);
        p.strokeWeight(1);
        for (let x = 0; x < p.width; x += GRID_SIZE) p.line(x, 0, x, p.height);
        for (let y = 0; y < p.height; y += GRID_SIZE) p.line(0, y, p.width, y);

        // Draw Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
            p.strokeWeight(wire.state ? 3 : 2);
            p.noFill();

            // Bezier curve for smooth aesthetic wiring (like the sketch)
            p.bezier(
              start.x, start.y, 
              start.x + 20, start.y, 
              end.x - 20, end.y, 
              end.x, end.y
            );
          }
        });

        // Draw Temp Wire (while dragging)
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            p.stroke(COLOR_WIRE_OFF);
            p.strokeWeight(2);
            p.line(start.x, start.y, p.mouseX, p.mouseY);
          }
        }

        // Draw Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });
      };

      // -- HELPERS --
      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): Point => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;
        const yStep = h / ((type === 'input' ? def.inputs : def.outputs) + 1);

        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep)
        };
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;

        p.push();
        p.translate(comp.x, comp.y);

        // Body
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        // Shape based on type (simplified for clean vector look)
        if (comp.type === ComponentType.AND || comp.type === ComponentType.NAND) {
          p.rect(0, 0, w/2, h);
          p.arc(w/2, h/2, w, h, -p.HALF_PI, p.HALF_PI);
          if (comp.type === ComponentType.NAND) p.circle(w + 5, h/2, 8);
        } else if (comp.type === ComponentType.OR || comp.type === ComponentType.NOR) {
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(w/2, 0, w/2, h, 0, h); // Curved back
          p.vertex(0, h);
          p.bezierVertex(w/2, h, w, h/2, w, h/2); // Point
          p.bezierVertex(w, h/2, w/2, 0, 0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NOR) p.circle(w + 2, h/2, 8);
        } else if (comp.type === ComponentType.NOT) {
          p.triangle(0, 0, 0, h, w-5, h/2);
          p.circle(w, h/2, 6);
        } else if (comp.type === ComponentType.XOR) {
          // Double curve back for XOR
          p.noFill();
          p.strokeWeight(2);
          p.arc(-5, h/2, w/2, h, -p.HALF_PI, p.HALF_PI);
          p.fill(COLOR_COMPONENT_BG);
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(w/2, 0, w/2, h, 0, h);
          p.vertex(0, h);
          p.bezierVertex(w/2, h, w, h/2, w, h/2);
          p.bezierVertex(w, h/2, w/2, 0, 0, 0);
          p.endShape(p.CLOSE);
        } else if (comp.type === ComponentType.INPUT_SWITCH) {
           p.rect(0, 0, w, h, 4);
           p.fill(comp.outputValues[0] ? COLOR_WIRE_ON : '#ddd');
           p.rect(4, 4, w-8, h-8, 2);
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           p.rect(0, 0, w, h, 4);
           p.fill(comp.inputValues[0] ? COLOR_WIRE_ON : '#333');
           p.circle(w/2, h/2, w-10);
        } else if (comp.type === ComponentType.HEX_DISPLAY) {
           p.rect(0, 0, w, h, 2);
           p.fill('#222');
           p.rect(4, 4, w-8, h-8);
           p.fill('red');
           p.textSize(20);
           // Calculate Hex value
           let val = 0;
           if(comp.inputValues[0]) val += 1;
           if(comp.inputValues[1]) val += 2;
           if(comp.inputValues[2]) val += 4;
           if(comp.inputValues[3]) val += 8;
           p.text(val.toString(16).toUpperCase(), w/2, h/2 + 2);
           p.textSize(12);
        } else {
           // Default Box
           p.rect(0, 0, w, h, 4);
        }

        p.noStroke();
        p.fill('#000');
        // Label inside
        if (comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED && comp.type !== ComponentType.HEX_DISPLAY) {
           p.text(def.label, w/2, h/2);
        }

        // Draw Ports
        p.fill('#64748b');
        // Inputs
        for (let i = 0; i < def.inputs; i++) {
           const y = ((i + 1) * (h / (def.inputs + 1)));
           p.circle(0, y, 6);
        }
        // Outputs
        for (let i = 0; i < def.outputs; i++) {
           const y = ((i + 1) * (h / (def.outputs + 1)));
           p.circle(w, y, 6);
        }

        p.pop();
      };

      const getHoveredPort = (x: number, y: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          // Check inputs
          for (let i = 0; i < def.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(x, y, pos.x, pos.y) < 10) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          // Check outputs
          for (let i = 0; i < def.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(x, y, pos.x, pos.y) < 10) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (x: number, y: number): string | null => {
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (x > comp.x && x < comp.x + (def.width * GRID_SIZE) &&
              y > comp.y && y < comp.y + (def.height * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS --
      p.mousePressed = () => {
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        // Reset dragging state
        isDraggingComp.current = false;

        // 1. Check for Port Click (Wiring)
        const port = getHoveredPort(p.mouseX, p.mouseY);
        if (port) {
          wiringStart.current = port;
          return;
        }

        // 2. Check for Component Click (Select/Drag)
        const compId = getHoveredComponent(p.mouseX, p.mouseY);
        if (compId) {
          if (tool === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             return;
          }

          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             // Prepare to drag
             draggingCompId.current = compId;
             dragOffset.current = { x: p.mouseX - comp.x, y: p.mouseY - comp.y };
          }
          return;
        }

        // 3. Place New Component (if tool selected via click)
        if (tool !== 'SELECT' && tool !== 'WIRE' && tool !== 'DELETE') {
           const def = COMPONENT_DEFINITIONS[tool];
           const snapX = Math.round(p.mouseX / GRID_SIZE) * GRID_SIZE;
           const snapY = Math.round(p.mouseY / GRID_SIZE) * GRID_SIZE;

           const newComp: CircuitComponent = {
             id: crypto.randomUUID(),
             type: tool,
             x: snapX,
             y: snapY,
             inputValues: new Array(def.inputs).fill(false),
             outputValues: new Array(def.outputs).fill(false)
           };
           componentsRef.current.push(newComp);
           onToolUsed(); 
        }
      };

      p.mouseDragged = () => {
        if (draggingCompId.current) {
          isDraggingComp.current = true; // Mark that we are indeed moving it
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp) {
            comp.x = Math.round((p.mouseX - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((p.mouseY - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
        }
      };

      p.mouseReleased = () => {
        // Handle Switch Toggle (Click without drag)
        if (draggingCompId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        draggingCompId.current = null;
        isDraggingComp.current = false;

        // Finish Wiring
        if (wiringStart.current) {
          const endPort = getHoveredPort(p.mouseX, p.mouseY);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            // Valid connection? (Output -> Input)
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            // Strict direction: Must be Output to Input
            if (src.type === 'output' && dst.type === 'input') {
              // Check if already connected (avoid dupes)
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );

              // Only one wire per input allowed for simplicity
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);

    return () => {
      p5InstanceRef.current?.remove();
    };
  }, [tool, isPlaying, tickSpeedMs, onToolUsed]);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
};

export default LogicCanvas;

import React, { useRef, useEffect, useState } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

interface LogicCanvasProps {
  tool: ComponentType | 'SELECT' | 'WIRE' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number;
  onToolUsed: () => void; // Reset tool after use if needed
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, onToolUsed }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State (Refs for performance to avoid React render loop interference with P5 loop) --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  // -- Interaction State --
  const draggingCompId = useRef<string | null>(null);
  const isDraggingComp = useRef<boolean>(false); // Track if we actually moved the mouse while holding component
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const mousePos = useRef<Point>({ x: 0, y: 0 });

  // -- Simulation Loop --
  useEffect(() => {
    if (!isPlaying) return;

    const interval = setInterval(() => {
      const result = stepSimulation(componentsRef.current, wiresRef.current);
      componentsRef.current = result.components;
      wiresRef.current = result.wires;
    }, tickSpeedMs);

    return () => clearInterval(interval);
  }, [isPlaying, tickSpeedMs]);

