import React, { useRef, useEffect } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number;
  // New props for touch drop handling
  pendingDrop?: { type: ComponentType, x: number, y: number } | null;
  onPendingDropHandled?: () => void;
  onToolUsed?: () => void; // Keeping for compatibility, though less used now
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, pendingDrop, onPendingDropHandled }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State (Refs for performance to avoid React render loop interference with P5 loop) --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  // -- Interaction State --
  const draggingCompId = useRef<string | null>(null);
  const isDraggingComp = useRef<boolean>(false); // Track if we actually moved the mouse while holding component
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });

  // -- Helper to add component --
  const addComponent = (type: ComponentType, x: number, y: number) => {
    const def = COMPONENT_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(def.inputs).fill(false),
      outputValues: new Array(def.outputs).fill(false)
    };

    componentsRef.current.push(newComp);
  };

  // -- Simulation Loop --
  useEffect(() => {
    if (!isPlaying) return;

    const interval = setInterval(() => {
      const result = stepSimulation(componentsRef.current, wiresRef.current);
      componentsRef.current = result.components;
      wiresRef.current = result.wires;
    }, tickSpeedMs);

    return () => clearInterval(interval);
  }, [isPlaying, tickSpeedMs]);

  // -- Handle Pending Drop (Touch) --
  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  // -- Drag and Drop from Sidebar Handlers (Desktop HTML5 DnD) --
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-logic-sim') as ComponentType;

    if (type && containerRef.current && COMPONENT_DEFINITIONS[type]) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      addComponent(type, x, y);
    }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current) return;

    // Dynamic import/usage of p5 (assuming loaded via CDN or npm)
    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    const sketch = (p: p5Types) => {

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10); // Smaller text for compact components
        p.textAlign(p.CENTER, p.CENTER);
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      // -- DRAW LOOP --
      p.draw = () => {
        p.background(COLOR_BG);

        // Draw Grid
        p.stroke(COLOR_GRID);
        p.strokeWeight(1);
        for (let x = 0; x < p.width; x += GRID_SIZE) p.line(x, 0, x, p.height);
        for (let y = 0; y < p.height; y += GRID_SIZE) p.line(0, y, p.width, y);

        // Draw Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
            p.strokeWeight(wire.state ? 3 : 2);
            p.noFill();

            // Bezier curve
            const cpOffset = GRID_SIZE * 0.5;
            p.bezier(
              start.x, start.y, 
              start.x + cpOffset, start.y, 
              end.x - cpOffset, end.y, 
              end.x, end.y
            );
          }
        });

        // Draw Temp Wire (while dragging)
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            p.stroke(COLOR_WIRE_OFF);
            p.strokeWeight(2);
            p.line(start.x, start.y, p.mouseX, p.mouseY);
          }
        }

        // Draw Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });
      };

      // -- HELPERS --
      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): Point => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;
        const yStep = h / ((type === 'input' ? def.inputs : def.outputs) + 1);

        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep)
        };
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;

        p.push();
        p.translate(comp.x, comp.y);

        // Body
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        // Shape based on type
        if (comp.type === ComponentType.AND || comp.type === ComponentType.NAND) {
          // AND
          p.beginShape();
          p.vertex(0, 0);
          p.vertex(0, h);
          p.vertex(w * 0.5, h);
          p.bezierVertex(w, h, w, 0, w * 0.5, 0); 
          p.vertex(0, 0);
          p.endShape(p.CLOSE);

          if (comp.type === ComponentType.NAND) {
            p.fill(COLOR_COMPONENT_BG);
            p.circle(w + 3, h / 2, 6);
          }
        } else if (comp.type === ComponentType.OR || comp.type === ComponentType.NOR) {
          // OR
          const curveDepth = w * 0.2; 
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);

          if (comp.type === ComponentType.NOR) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(w + 2, h / 2, 6);
          }
        } else if (comp.type === ComponentType.NOT) {
          p.triangle(0, 0, 0, h, w - 5, h / 2);
          p.fill(COLOR_COMPONENT_BG);
          p.circle(w, h / 2, 6);
        } else if (comp.type === ComponentType.XOR) {
          const curveDepth = w * 0.2;
          // Back line
          p.noFill();
          p.strokeWeight(2);
          p.beginShape();
          p.vertex(-4, 0);
          p.bezierVertex(-4 + curveDepth, h * 0.1, -4 + curveDepth, h * 0.9, -4, h);
          p.endShape();
          // Body
          p.fill(COLOR_COMPONENT_BG);
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);

        } else if (comp.type === ComponentType.INPUT_SWITCH) {
           const isOn = comp.outputValues[0];
           p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
           p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
           p.rect(0, 0, w, h, 6); 
           p.noStroke();
           p.fill(isOn ? '#fff' : '#475569');
           p.text(isOn ? "ON" : "OFF", w/2, h/2);

        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const isOn = comp.inputValues[0];
           p.noStroke();
           if (isOn) {
              p.fill(245, 158, 11, 80);
              p.circle(w/2, h/2, w * 0.9);
           }
           p.fill(isOn ? COLOR_WIRE_ON : '#334155');
           p.circle(w/2, h/2, w * 0.6);

        } else if (comp.type === ComponentType.HEX_DISPLAY) {
           p.fill('#0f172a');
           p.stroke('#334155');
           p.rect(0, 0, w, h, 4);
           p.noStroke();
           p.fill('#ef4444'); 
           p.textSize(18);
           let val = 0;
           if(comp.inputValues[0]) val += 1;
           if(comp.inputValues[1]) val += 2;
           if(comp.inputValues[2]) val += 4;
           if(comp.inputValues[3]) val += 8;
           p.text(val.toString(16).toUpperCase(), w/2, h/2 + 2);
           p.textSize(10);

        } else {
           p.rect(0, 0, w, h, 4);
           p.fill('#000');
           p.text(def.label.substring(0,3), w/2, h/2);
        }

        p.noStroke();
        p.fill('#000');

        // Draw Ports
        p.fill('#64748b');
        for (let i = 0; i < def.inputs; i++) {
           const y = ((i + 1) * (h / (def.inputs + 1)));
           p.circle(0, y, 5);
        }
        for (let i = 0; i < def.outputs; i++) {
           const y = ((i + 1) * (h / (def.outputs + 1)));
           p.circle(w, y, 5);
        }

        p.pop();
      };

      const getHoveredPort = (x: number, y: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        const HIT_RADIUS = 12; // Slightly larger hit area for ease of use

        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          for (let i = 0; i < def.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          for (let i = 0; i < def.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (x: number, y: number): string | null => {
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (x > comp.x && x < comp.x + (def.width * GRID_SIZE) &&
              y > comp.y && y < comp.y + (def.height * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS --
      p.mousePressed = () => {
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        isDraggingComp.current = false;

        // 1. Wiring (Priority)
        const port = getHoveredPort(p.mouseX, p.mouseY);
        if (port) {
          wiringStart.current = port;
          return;
        }

        // 2. Select / Drag / Delete Component
        const compId = getHoveredComponent(p.mouseX, p.mouseY);
        if (compId) {
          if (tool === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             return;
          }

          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             draggingCompId.current = compId;
             dragOffset.current = { x: p.mouseX - comp.x, y: p.mouseY - comp.y };
          }
          return;
        }

        // REMOVED: Click-to-place logic (ComponentType checking)
        // Now placement happens solely via Drag & Drop (HTML5 or Touch)
      };

      p.mouseDragged = () => {
        if (draggingCompId.current) {
          isDraggingComp.current = true;
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp) {
            comp.x = Math.round((p.mouseX - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((p.mouseY - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
        }
      };

      p.mouseReleased = () => {
        // Handle Switch Toggle
        if (draggingCompId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        draggingCompId.current = null;
        isDraggingComp.current = false;

        // Finish Wiring
        if (wiringStart.current) {
          const endPort = getHoveredPort(p.mouseX, p.mouseY);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);

    return () => {
      p5InstanceRef.current?.remove();
    };
  }, [tool, isPlaying, tickSpeedMs]); // pendingDrop is handled in separate useEffect

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
};

export default LogicCanvas;

import React, { useRef, useEffect } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; // Used as "Simulation Steps per Frame" multiplier roughly, or simply control update frequency
  // New props for touch drop handling
  pendingDrop?: { type: ComponentType, x: number, y: number } | null;
  onPendingDropHandled?: () => void;
  onToolUsed?: () => void;
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, pendingDrop, onPendingDropHandled }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  // -- Interaction State --
  const draggingCompId = useRef<string | null>(null);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });

  // Track last simulation time for consistent timing if needed, 
  // but for logic circuits, running per-frame with sub-steps creates the smoothest "real-time" feel.
  const lastStepTime = useRef<number>(0);

  // -- Helper to add component --
  const addComponent = (type: ComponentType, x: number, y: number) => {
    const def = COMPONENT_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(def.inputs).fill(false),
      outputValues: new Array(def.outputs).fill(false)
    };

    componentsRef.current.push(newComp);
  };

  // -- Handle Pending Drop (Touch) --
  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  // -- Drag and Drop (Desktop) --
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-logic-sim') as ComponentType;
    if (type && containerRef.current && COMPONENT_DEFINITIONS[type]) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      addComponent(type, x, y);
    }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current) return;

    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    const sketch = (p: p5Types) => {

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10);
        p.textAlign(p.CENTER, p.CENTER);
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      // -- MAIN LOOP --
      p.draw = () => {
        p.background(COLOR_BG);

        // -- SIMULATION STEP --
        // Run logic simulation inside the draw loop for better synchronization and performance.
        // Instead of setInterval, we use the frame loop.
        // We implement "Sub-stepping": running the logic multiple times per frame.
        // This allows signals to propagate through multiple gates instantly from the user's perspective,
        // which is crucial for flip-flops and complex combinational logic to appear "real-time".

        if (isPlaying) {
          // Determine how many steps to run per frame based on tickSpeedMs.
          // Lower tickSpeedMs (e.g. 10ms) -> More steps per frame (Faster).
          // Higher tickSpeedMs (e.g. 500ms) -> Fewer steps, or skip frames.

          // Strategy: Treat tickSpeedMs as "Delay between ticks".
          // If tickSpeed is very low (< 20ms), we treat it as "High Performance Mode" and run multiple steps per frame.
          // If tickSpeed is high, we respect the time delay.

          const now = p.millis();

          if (tickSpeedMs < 20) {
            // High speed mode: Run multiple iterations per frame to simulate propagation
            // 16ms per frame. If tickSpeed is 1ms, run 16 times. 
            // We cap it to avoid freezing.
            const steps = Math.min(10, Math.ceil(20 / Math.max(1, tickSpeedMs)));
            for(let i=0; i<steps; i++) {
              const result = stepSimulation(componentsRef.current, wiresRef.current);
              componentsRef.current = result.components;
              wiresRef.current = result.wires;
            }
          } else {
            // Standard timer based mode
            if (now - lastStepTime.current > tickSpeedMs) {
              const result = stepSimulation(componentsRef.current, wiresRef.current);
              componentsRef.current = result.components;
              wiresRef.current = result.wires;
              lastStepTime.current = now;
            }
          }
        }

        // -- RENDERING --

        // Grid
        p.stroke(COLOR_GRID);
        p.strokeWeight(1);
        for (let x = 0; x < p.width; x += GRID_SIZE) p.line(x, 0, x, p.height);
        for (let y = 0; y < p.height; y += GRID_SIZE) p.line(0, y, p.width, y);

        // Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
            p.strokeWeight(wire.state ? 3 : 2);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            p.bezier(
              start.x, start.y, 
              start.x + cpOffset, start.y, 
              end.x - cpOffset, end.y, 
              end.x, end.y
            );
          }
        });

        // Temp Wire
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            p.stroke(COLOR_WIRE_OFF);
            p.strokeWeight(2);
            p.line(start.x, start.y, p.mouseX, p.mouseY);
          }
        }

        // Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });
      };

      // -- HELPERS --
      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): Point => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;
        const yStep = h / ((type === 'input' ? def.inputs : def.outputs) + 1);

        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep)
        };
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;

        p.push();
        p.translate(comp.x, comp.y);

        // Body
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        if (comp.type === ComponentType.AND || comp.type === ComponentType.NAND) {
          p.beginShape();
          p.vertex(0, 0);
          p.vertex(0, h);
          p.vertex(w * 0.5, h);
          p.bezierVertex(w, h, w, 0, w * 0.5, 0); 
          p.vertex(0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NAND) {
            p.fill(COLOR_COMPONENT_BG);
            p.circle(w + 3, h / 2, 6);
          }
        } else if (comp.type === ComponentType.OR || comp.type === ComponentType.NOR) {
          const curveDepth = w * 0.2; 
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NOR) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(w + 2, h / 2, 6);
          }
        } else if (comp.type === ComponentType.NOT) {
          p.triangle(0, 0, 0, h, w - 5, h / 2);
          p.fill(COLOR_COMPONENT_BG);
          p.circle(w, h / 2, 6);
        } else if (comp.type === ComponentType.XOR) {
          const curveDepth = w * 0.2;
          p.noFill();
          p.strokeWeight(2);
          p.beginShape();
          p.vertex(-4, 0);
          p.bezierVertex(-4 + curveDepth, h * 0.1, -4 + curveDepth, h * 0.9, -4, h);
          p.endShape();
          p.fill(COLOR_COMPONENT_BG);
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);
        } else if (comp.type === ComponentType.INPUT_SWITCH) {
           const isOn = comp.outputValues[0];
           p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
           p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
           p.rect(0, 0, w, h, 6); 
           p.noStroke();
           p.fill(isOn ? '#fff' : '#475569');
           p.text(isOn ? "ON" : "OFF", w/2, h/2);
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const isOn = comp.inputValues[0];
           p.noStroke();
           if (isOn) {
              p.fill(245, 158, 11, 80);
              p.circle(w/2, h/2, w * 0.9);
           }
           p.fill(isOn ? COLOR_WIRE_ON : '#334155');
           p.circle(w/2, h/2, w * 0.6);
        } else if (comp.type === ComponentType.HEX_DISPLAY) {
           p.fill('#0f172a');
           p.stroke('#334155');
           p.rect(0, 0, w, h, 4);
           p.noStroke();
           p.fill('#ef4444'); 
           p.textSize(18);
           let val = 0;
           if(comp.inputValues[0]) val += 1;
           if(comp.inputValues[1]) val += 2;
           if(comp.inputValues[2]) val += 4;
           if(comp.inputValues[3]) val += 8;
           p.text(val.toString(16).toUpperCase(), w/2, h/2 + 2);
           p.textSize(10);
        } else {
           p.rect(0, 0, w, h, 4);
           p.fill('#000');
           p.text(def.label.substring(0,3), w/2, h/2);
        }

        p.noStroke();
        p.fill('#000');

        // Ports
        p.fill('#64748b');
        for (let i = 0; i < def.inputs; i++) {
           const y = ((i + 1) * (h / (def.inputs + 1)));
           p.circle(0, y, 5);
        }
        for (let i = 0; i < def.outputs; i++) {
           const y = ((i + 1) * (h / (def.outputs + 1)));
           p.circle(w, y, 5);
        }

        p.pop();
      };

      const getHoveredPort = (x: number, y: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          for (let i = 0; i < def.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          for (let i = 0; i < def.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (x: number, y: number): string | null => {
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (x > comp.x && x < comp.x + (def.width * GRID_SIZE) &&
              y > comp.y && y < comp.y + (def.height * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS --
      p.mousePressed = () => {
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        isDraggingComp.current = false;

        const port = getHoveredPort(p.mouseX, p.mouseY);
        if (port) {
          wiringStart.current = port;
          return;
        }

        const compId = getHoveredComponent(p.mouseX, p.mouseY);
        if (compId) {
          if (tool === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             return;
          }

          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             draggingCompId.current = compId;
             dragOffset.current = { x: p.mouseX - comp.x, y: p.mouseY - comp.y };
          }
          return;
        }
      };

      p.mouseDragged = () => {
        if (draggingCompId.current) {
          isDraggingComp.current = true;
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp) {
            comp.x = Math.round((p.mouseX - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((p.mouseY - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
        }
      };

      p.mouseReleased = () => {
        if (draggingCompId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        draggingCompId.current = null;
        isDraggingComp.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(p.mouseX, p.mouseY);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);

    return () => {
      p5InstanceRef.current?.remove();
    };
  }, [tool, isPlaying, tickSpeedMs]);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
};

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas from './components/LogicCanvas';
import { ComponentType } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

/**
 * LogicFlow Simulator
 * 
 * Philosophy:
 * - Simple over Complex: UI is kept minimal to focus on the circuit.
 * - Solid Foundations: The P5 engine handles the heavy lifting of 60fps rendering,
 *   while React handles the accessible UI layer.
 * - Extensibility: New gates are added in constants.ts only.
 */

const App: React.FC = () => {
  // Tools: SELECT, DELETE. Note: Placing components is now done via Drag & Drop only.
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(true);
  const [tickSpeed, setTickSpeed] = useState(10); // ms - Default to fast for responsiveness

  // -- Touch Drag & Drop State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);

  // Queue for components added via Touch DnD to be consumed by LogicCanvas
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);

  // -- Touch Event Handlers for Mobile DnD --
  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent) => {
    // Prevent default to stop scrolling while dragging an item
    // e.preventDefault(); // Using touch-action: none in CSS is better
    const touch = e.touches[0];
    setDraggedType(type);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); // Stop scrolling
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        // Check if dropped within canvas bounds
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          // Calculate relative position
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;

          setPendingDrop({ type: draggedType, x: relX, y: relY });
        }
      }
      // Reset
      setDraggedType(null);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => {
          if (t === 'SELECT' || t === 'DELETE') {
            setSelectedTool(t);
          }
        }}
        onTouchStartItem={handleTouchStartItem}
      />

      <main className="flex-1 flex flex-col relative">

        {/* Top Toolbar / HUD */}
        <div className="absolute top-4 left-4 right-4 h-14 bg-white/90 backdrop-blur shadow-sm rounded-lg flex items-center justify-between px-6 z-10 border border-slate-200 pointer-events-auto">
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></span>
               <span className="text-sm font-semibold text-slate-600">{isPlaying ? 'Running' : 'Paused'}</span>
             </div>

             <div className="h-6 w-px bg-slate-200 mx-2"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-3 py-1 bg-slate-100 hover:bg-slate-200 rounded text-sm font-medium transition-colors"
             >
               {isPlaying ? 'Pause' : 'Run'}
             </button>

             <button 
                onClick={() => window.location.reload()}
                className="px-3 py-1 text-red-500 hover:bg-red-50 rounded text-sm font-medium transition-colors"
              >
                Clear All
              </button>
          </div>

          <div className="flex items-center space-x-3">
            <span className="text-xs text-slate-400 font-medium uppercase">Delay (ms)</span>
            <input 
              type="range" 
              min="1" 
              max="500" 
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-32 accent-blue-600"
            />
            <span className="text-xs text-slate-500 w-12 text-right">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            onPendingDropHandled={handlePendingDropHandled}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {COMPONENT_DEFINITIONS[draggedType].label}
              </span>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import { CircuitComponent, Wire, ComponentType } from '../types';

/**
 * Logic Engine Philosophy:
 * - Deterministic: Given inputs, output is calculated.
 * - Discrete Time: Updates occur in "ticks".
 * - Separation: This engine does not know about coordinates or rendering.
 */

// Evaluate a single component based on its current inputs
const evaluateComponent = (comp: CircuitComponent): boolean[] => {
  const inputs = comp.inputValues;

  switch (comp.type) {
    case ComponentType.INPUT_SWITCH:
      // Input switch state is toggled manually by user, logic doesn't change it unless reset
      return comp.outputValues; 

    case ComponentType.OUTPUT_LED:
    case ComponentType.HEX_DISPLAY:
      return []; // No outputs

    case ComponentType.NOT:
      return [!inputs[0]];

    case ComponentType.AND:
      return [inputs[0] && inputs[1]];

    case ComponentType.OR:
      return [inputs[0] || inputs[1]];

    case ComponentType.NAND:
      return [!(inputs[0] && inputs[1])];

    case ComponentType.NOR:
      return [!(inputs[0] || inputs[1])];

    case ComponentType.XOR:
      return [(inputs[0] ? 1 : 0) !== (inputs[1] ? 1 : 0)];

    default:
      return comp.outputValues;
  }
};

/**
 * Performs one simulation tick.
 * 1. Transfers values from Output Ports to Input Ports via Wires.
 * 2. Calculates new Output Port values for all Components.
 */
export const stepSimulation = (
  components: CircuitComponent[],
  wires: Wire[]
): { components: CircuitComponent[], wires: Wire[] } => {

  // Optimization: Create a Map for O(1) access to components by ID
  // This is crucial when running 50+ steps per frame
  const compMap = new Map<string, CircuitComponent>();

  // Clone to avoid mutation side-effects during calculation
  const nextComponents = components.map(c => {
    const nextC = {
      ...c,
      inputValues: [...c.inputValues],
      outputValues: [...c.outputValues]
    };
    compMap.set(nextC.id, nextC);
    return nextC;
  });

  const nextWires = wires.map(w => ({ ...w }));

  // 1. Propagate Signals: Update Component Inputs based on Wires
  // A wire takes the value from the Source Component's output and applies it to the Dest Component's input.
  nextWires.forEach(wire => {
    const sourceComp = compMap.get(wire.fromCompId);
    const destComp = compMap.get(wire.toCompId);

    if (sourceComp && destComp) {
      // Get signal from previous tick state of source
      const signal = sourceComp.outputValues[wire.fromPortIndex] || false;
      wire.state = signal; // Update wire visual state

      // Apply to destination input
      if (destComp.inputValues[wire.toPortIndex] !== signal) {
        destComp.inputValues[wire.toPortIndex] = signal;
      }
    }
  });

  // 2. Compute Logic: Update Component Outputs based on new Inputs
  nextComponents.forEach(comp => {
    // Input switches are special; their output is controlled by user interaction, not logic flow here
    if (comp.type !== ComponentType.INPUT_SWITCH) {
      comp.outputValues = evaluateComponent(comp);
    }
  });

  return { components: nextComponents, wires: nextWires };
};

import React, { useRef, useEffect } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; // Used as "Simulation Steps per Frame" multiplier roughly, or simply control update frequency
  // New props for touch drop handling
  pendingDrop?: { type: ComponentType, x: number, y: number } | null;
  onPendingDropHandled?: () => void;
  onToolUsed?: () => void;
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, pendingDrop, onPendingDropHandled }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  // -- Interaction State --
  const draggingCompId = useRef<string | null>(null);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });

  const lastStepTime = useRef<number>(0);

  // -- Helper to add component --
  const addComponent = (type: ComponentType, x: number, y: number) => {
    const def = COMPONENT_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(def.inputs).fill(false),
      outputValues: new Array(def.outputs).fill(false)
    };

    componentsRef.current.push(newComp);
  };

  // -- Handle Pending Drop (Touch) --
  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  // -- Drag and Drop (Desktop) --
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-logic-sim') as ComponentType;
    if (type && containerRef.current && COMPONENT_DEFINITIONS[type]) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      addComponent(type, x, y);
    }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current) return;

    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    const sketch = (p: p5Types) => {

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10);
        p.textAlign(p.CENTER, p.CENTER);
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      // -- MAIN LOOP --
      p.draw = () => {
        p.background(COLOR_BG);

        // -- SIMULATION STEP --
        if (isPlaying) {
          const now = p.millis();

          // Turbo Mode (Instant Propagation)
          // If delay is very low, we run many simulation steps per frame (sub-stepping).
          // This allows feedback loops (like flip-flops) to stabilize within a single visual frame.
          if (tickSpeedMs <= 5) {
             // 50 sub-steps is enough for most complex educational circuits (like 8-bit adders or latches)
             // to appear instant.
             for(let i=0; i<50; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
             }
          } 
          // Fast Mode (semi-instant)
          else if (tickSpeedMs < 20) {
            const steps = Math.min(20, Math.ceil(20 / Math.max(1, tickSpeedMs)));
            for(let i=0; i<steps; i++) {
              const result = stepSimulation(componentsRef.current, wiresRef.current);
              componentsRef.current = result.components;
              wiresRef.current = result.wires;
            }
          } 
          // Standard Timer Mode (Visible propagation)
          else {
            if (now - lastStepTime.current > tickSpeedMs) {
              const result = stepSimulation(componentsRef.current, wiresRef.current);
              componentsRef.current = result.components;
              wiresRef.current = result.wires;
              lastStepTime.current = now;
            }
          }
        }

        // -- RENDERING --

        // Grid
        p.stroke(COLOR_GRID);
        p.strokeWeight(1);
        for (let x = 0; x < p.width; x += GRID_SIZE) p.line(x, 0, x, p.height);
        for (let y = 0; y < p.height; y += GRID_SIZE) p.line(0, y, p.width, y);

        // Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
            p.strokeWeight(wire.state ? 3 : 2);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            p.bezier(
              start.x, start.y, 
              start.x + cpOffset, start.y, 
              end.x - cpOffset, end.y, 
              end.x, end.y
            );
          }
        });

        // Temp Wire
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            p.stroke(COLOR_WIRE_OFF);
            p.strokeWeight(2);
            p.line(start.x, start.y, p.mouseX, p.mouseY);
          }
        }

        // Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });
      };

      // -- HELPERS --
      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): Point => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;
        const yStep = h / ((type === 'input' ? def.inputs : def.outputs) + 1);

        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep)
        };
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;

        p.push();
        p.translate(comp.x, comp.y);

        // Body
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        if (comp.type === ComponentType.AND || comp.type === ComponentType.NAND) {
          p.beginShape();
          p.vertex(0, 0);
          p.vertex(0, h);
          p.vertex(w * 0.5, h);
          p.bezierVertex(w, h, w, 0, w * 0.5, 0); 
          p.vertex(0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NAND) {
            p.fill(COLOR_COMPONENT_BG);
            p.circle(w + 3, h / 2, 6);
          }
        } else if (comp.type === ComponentType.OR || comp.type === ComponentType.NOR) {
          const curveDepth = w * 0.2; 
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NOR) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(w + 2, h / 2, 6);
          }
        } else if (comp.type === ComponentType.NOT) {
          p.triangle(0, 0, 0, h, w - 5, h / 2);
          p.fill(COLOR_COMPONENT_BG);
          p.circle(w, h / 2, 6);
        } else if (comp.type === ComponentType.XOR) {
          const curveDepth = w * 0.2;
          p.noFill();
          p.strokeWeight(2);
          p.beginShape();
          p.vertex(-4, 0);
          p.bezierVertex(-4 + curveDepth, h * 0.1, -4 + curveDepth, h * 0.9, -4, h);
          p.endShape();
          p.fill(COLOR_COMPONENT_BG);
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);
        } else if (comp.type === ComponentType.INPUT_SWITCH) {
           const isOn = comp.outputValues[0];
           p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
           p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
           p.rect(0, 0, w, h, 6); 
           p.noStroke();
           p.fill(isOn ? '#fff' : '#475569');
           p.text(isOn ? "ON" : "OFF", w/2, h/2);
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const isOn = comp.inputValues[0];
           p.noStroke();
           if (isOn) {
              p.fill(245, 158, 11, 80);
              p.circle(w/2, h/2, w * 0.9);
           }
           p.fill(isOn ? COLOR_WIRE_ON : '#334155');
           p.circle(w/2, h/2, w * 0.6);
        } else if (comp.type === ComponentType.HEX_DISPLAY) {
           p.fill('#0f172a');
           p.stroke('#334155');
           p.rect(0, 0, w, h, 4);
           p.noStroke();
           p.fill('#ef4444'); 
           p.textSize(18);
           let val = 0;
           if(comp.inputValues[0]) val += 1;
           if(comp.inputValues[1]) val += 2;
           if(comp.inputValues[2]) val += 4;
           if(comp.inputValues[3]) val += 8;
           p.text(val.toString(16).toUpperCase(), w/2, h/2 + 2);
           p.textSize(10);
        } else {
           p.rect(0, 0, w, h, 4);
           p.fill('#000');
           p.text(def.label.substring(0,3), w/2, h/2);
        }

        p.noStroke();
        p.fill('#000');

        // Ports
        p.fill('#64748b');
        for (let i = 0; i < def.inputs; i++) {
           const y = ((i + 1) * (h / (def.inputs + 1)));
           p.circle(0, y, 5);
        }
        for (let i = 0; i < def.outputs; i++) {
           const y = ((i + 1) * (h / (def.outputs + 1)));
           p.circle(w, y, 5);
        }

        p.pop();
      };

      const getHoveredPort = (x: number, y: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          for (let i = 0; i < def.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          for (let i = 0; i < def.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (x: number, y: number): string | null => {
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (x > comp.x && x < comp.x + (def.width * GRID_SIZE) &&
              y > comp.y && y < comp.y + (def.height * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS --
      p.mousePressed = () => {
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        isDraggingComp.current = false;

        const port = getHoveredPort(p.mouseX, p.mouseY);
        if (port) {
          wiringStart.current = port;
          return;
        }

        const compId = getHoveredComponent(p.mouseX, p.mouseY);
        if (compId) {
          if (tool === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             return;
          }

          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             draggingCompId.current = compId;
             dragOffset.current = { x: p.mouseX - comp.x, y: p.mouseY - comp.y };
          }
          return;
        }
      };

      p.mouseDragged = () => {
        if (draggingCompId.current) {
          isDraggingComp.current = true;
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp) {
            comp.x = Math.round((p.mouseX - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((p.mouseY - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
        }
      };

      p.mouseReleased = () => {
        if (draggingCompId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        draggingCompId.current = null;
        isDraggingComp.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(p.mouseX, p.mouseY);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);

    return () => {
      p5InstanceRef.current?.remove();
    };
  }, [tool, isPlaying, tickSpeedMs]);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
};

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas from './components/LogicCanvas';
import { ComponentType } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

/**
 * LogicFlow Simulator
 * 
 * Philosophy:
 * - Simple over Complex: UI is kept minimal to focus on the circuit.
 * - Solid Foundations: The P5 engine handles the heavy lifting of 60fps rendering,
 *   while React handles the accessible UI layer.
 * - Extensibility: New gates are added in constants.ts only.
 */

const App: React.FC = () => {
  // Tools: SELECT, DELETE. Note: Placing components is now done via Drag & Drop only.
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(true);
  const [tickSpeed, setTickSpeed] = useState(5); // ms - Default to 5ms (Turbo Mode) for instant propagation

  // -- Touch Drag & Drop State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);

  // Queue for components added via Touch DnD to be consumed by LogicCanvas
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);

  // -- Touch Event Handlers for Mobile DnD --
  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent) => {
    // Prevent default to stop scrolling while dragging an item
    // e.preventDefault(); // Using touch-action: none in CSS is better
    const touch = e.touches[0];
    setDraggedType(type);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); // Stop scrolling
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        // Check if dropped within canvas bounds
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          // Calculate relative position
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;

          setPendingDrop({ type: draggedType, x: relX, y: relY });
        }
      }
      // Reset
      setDraggedType(null);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => {
          if (t === 'SELECT' || t === 'DELETE') {
            setSelectedTool(t);
          }
        }}
        onTouchStartItem={handleTouchStartItem}
      />

      <main className="flex-1 flex flex-col relative">

        {/* Top Toolbar / HUD */}
        <div className="absolute top-4 left-4 right-4 h-14 bg-white/90 backdrop-blur shadow-sm rounded-lg flex items-center justify-between px-6 z-10 border border-slate-200 pointer-events-auto">
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></span>
               <span className="text-sm font-semibold text-slate-600">{isPlaying ? 'Running' : 'Paused'}</span>
             </div>

             <div className="h-6 w-px bg-slate-200 mx-2"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-3 py-1 bg-slate-100 hover:bg-slate-200 rounded text-sm font-medium transition-colors"
             >
               {isPlaying ? 'Pause' : 'Run'}
             </button>

             <button 
                onClick={() => window.location.reload()}
                className="px-3 py-1 text-red-500 hover:bg-red-50 rounded text-sm font-medium transition-colors"
              >
                Clear All
              </button>
          </div>

          <div className="flex items-center space-x-3">
            <span className="text-xs text-slate-400 font-medium uppercase">Delay (ms)</span>
            <input 
              type="range" 
              min="1" 
              max="500" 
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-32 accent-blue-600"
            />
            <span className="text-xs text-slate-500 w-12 text-right">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            onPendingDropHandled={handlePendingDropHandled}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {COMPONENT_DEFINITIONS[draggedType].label}
              </span>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number } | null;
  onPendingDropHandled?: () => void;
  onToolUsed?: () => void;
}

const LogicCanvas: React.FC<LogicCanvasProps> = ({ tool, isPlaying, tickSpeedMs, pendingDrop, onPendingDropHandled }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State --
  const componentsRef = useRef<CircuitComponent[]>([]);
  const wiresRef = useRef<Wire[]>([]);

  // -- Interaction State --
  const draggingCompId = useRef<string | null>(null);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 });

  // Timer for discrete simulation steps
  const accumulatorRef = useRef<number>(0);

  // -- Helper to add component --
  const addComponent = (type: ComponentType, x: number, y: number) => {
    const def = COMPONENT_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(def.inputs).fill(false),
      outputValues: new Array(def.outputs).fill(false)
    };

    componentsRef.current.push(newComp);
  };

  // -- Handle Pending Drop (Touch) --
  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  // -- Drag and Drop (Desktop) --
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-logic-sim') as ComponentType;
    if (type && containerRef.current && COMPONENT_DEFINITIONS[type]) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      addComponent(type, x, y);
    }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current) return;

    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    const sketch = (p: p5Types) => {

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10);
        p.textAlign(p.CENTER, p.CENTER);
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      // -- MAIN LOOP --
      p.draw = () => {
        p.background(COLOR_BG);

        // -- SIMULATION STEP --
        if (isPlaying) {
          // Accumulate elapsed time (deltaTime is in milliseconds)
          accumulatorRef.current += p.deltaTime;

          // If enough time has passed for one or more ticks
          if (accumulatorRef.current >= tickSpeedMs) {
            // Run exactly one simulation step per interval to ensure visible state changes (blinking)
            // Even if we are behind multiple ticks, we only process one to avoid "skipping" visual states
            // in an oscillator. However, for real-time accuracy we might want to catch up.
            // Given the user wants to SEE blinking, one tick per visual update is safer if the speed is fast.
            // But if speed is slow, we just run once.

            // To support "Turbo" but still allow blinking if the user sets it slow:
            // We loop until we consume the accumulator, BUT we limit the loop to avoid freezing.

            // For the specific request "It should blink" (Oscillation visualization):
            // We should just run ONCE if the timer triggers. This effectively caps the logic FPS to the visual FPS
            // if tickSpeed is very low (e.g. 1ms), preventing sub-frame oscillation aliasing.

            const result = stepSimulation(componentsRef.current, wiresRef.current);
            componentsRef.current = result.components;
            wiresRef.current = result.wires;

            // Reset accumulator. 
            // If we want precise timing we subtract tickSpeedMs, but to prevent spiral of death or super-fast 
            // invisible osc, we just set to 0 or modulus.
            // For visualization purposes, resetting to 0 (or keeping remainder) with a cap is best.
            accumulatorRef.current = accumulatorRef.current % tickSpeedMs; 
          }
        }

        // -- RENDERING --

        // Grid
        p.stroke(COLOR_GRID);
        p.strokeWeight(1);
        for (let x = 0; x < p.width; x += GRID_SIZE) p.line(x, 0, x, p.height);
        for (let y = 0; y < p.height; y += GRID_SIZE) p.line(0, y, p.width, y);

        // Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
            p.strokeWeight(wire.state ? 3 : 2);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            p.bezier(
              start.x, start.y, 
              start.x + cpOffset, start.y, 
              end.x - cpOffset, end.y, 
              end.x, end.y
            );
          }
        });

        // Temp Wire
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            p.stroke(COLOR_WIRE_OFF);
            p.strokeWeight(2);
            p.line(start.x, start.y, p.mouseX, p.mouseY);
          }
        }

        // Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });
      };

      // -- HELPERS --
      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): Point => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;
        const yStep = h / ((type === 'input' ? def.inputs : def.outputs) + 1);

        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep)
        };
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const def = COMPONENT_DEFINITIONS[comp.type];
        const w = def.width * GRID_SIZE;
        const h = def.height * GRID_SIZE;

        p.push();
        p.translate(comp.x, comp.y);

        // Body
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        if (comp.type === ComponentType.AND || comp.type === ComponentType.NAND) {
          p.beginShape();
          p.vertex(0, 0);
          p.vertex(0, h);
          p.vertex(w * 0.5, h);
          p.bezierVertex(w, h, w, 0, w * 0.5, 0); 
          p.vertex(0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NAND) {
            p.fill(COLOR_COMPONENT_BG);
            p.circle(w + 3, h / 2, 6);
          }
        } else if (comp.type === ComponentType.OR || comp.type === ComponentType.NOR) {
          const curveDepth = w * 0.2; 
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);
          if (comp.type === ComponentType.NOR) {
             p.fill(COLOR_COMPONENT_BG);
             p.circle(w + 2, h / 2, 6);
          }
        } else if (comp.type === ComponentType.NOT) {
          p.triangle(0, 0, 0, h, w - 5, h / 2);
          p.fill(COLOR_COMPONENT_BG);
          p.circle(w, h / 2, 6);
        } else if (comp.type === ComponentType.XOR) {
          const curveDepth = w * 0.2;
          p.noFill();
          p.strokeWeight(2);
          p.beginShape();
          p.vertex(-4, 0);
          p.bezierVertex(-4 + curveDepth, h * 0.1, -4 + curveDepth, h * 0.9, -4, h);
          p.endShape();
          p.fill(COLOR_COMPONENT_BG);
          p.beginShape();
          p.vertex(0, 0);
          p.bezierVertex(curveDepth, h * 0.1, curveDepth, h * 0.9, 0, h);
          p.bezierVertex(w * 0.6, h, w, h * 0.5, w, h * 0.5);
          p.bezierVertex(w, h * 0.5, w * 0.6, 0, 0, 0);
          p.endShape(p.CLOSE);
        } else if (comp.type === ComponentType.INPUT_SWITCH) {
           const isOn = comp.outputValues[0];
           p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
           p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);
           p.rect(0, 0, w, h, 6); 
           p.noStroke();
           p.fill(isOn ? '#fff' : '#475569');
           p.text(isOn ? "ON" : "OFF", w/2, h/2);
        } else if (comp.type === ComponentType.OUTPUT_LED) {
           const isOn = comp.inputValues[0];
           p.noStroke();
           if (isOn) {
              p.fill(245, 158, 11, 80); // Amber glow
              p.circle(w/2, h/2, w * 0.9);
           }
           p.fill(isOn ? COLOR_WIRE_ON : '#334155');
           p.circle(w/2, h/2, w * 0.6);
        } else if (comp.type === ComponentType.HEX_DISPLAY) {
           p.fill('#0f172a');
           p.stroke('#334155');
           p.rect(0, 0, w, h, 4);
           p.noStroke();
           p.fill('#ef4444'); 
           p.textSize(18);
           let val = 0;
           if(comp.inputValues[0]) val += 1;
           if(comp.inputValues[1]) val += 2;
           if(comp.inputValues[2]) val += 4;
           if(comp.inputValues[3]) val += 8;
           p.text(val.toString(16).toUpperCase(), w/2, h/2 + 2);
           p.textSize(10);
        } else {
           p.rect(0, 0, w, h, 4);
           p.fill('#000');
           p.text(def.label.substring(0,3), w/2, h/2);
        }

        p.noStroke();
        p.fill('#000');

        // Ports
        p.fill('#64748b');
        for (let i = 0; i < def.inputs; i++) {
           const y = ((i + 1) * (h / (def.inputs + 1)));
           p.circle(0, y, 5);
        }
        for (let i = 0; i < def.outputs; i++) {
           const y = ((i + 1) * (h / (def.outputs + 1)));
           p.circle(w, y, 5);
        }

        p.pop();
      };

      const getHoveredPort = (x: number, y: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          for (let i = 0; i < def.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          for (let i = 0; i < def.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(x, y, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (x: number, y: number): string | null => {
        for (const comp of componentsRef.current) {
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (x > comp.x && x < comp.x + (def.width * GRID_SIZE) &&
              y > comp.y && y < comp.y + (def.height * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS --
      p.mousePressed = () => {
        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        isDraggingComp.current = false;

        const port = getHoveredPort(p.mouseX, p.mouseY);
        if (port) {
          wiringStart.current = port;
          return;
        }

        const compId = getHoveredComponent(p.mouseX, p.mouseY);
        if (compId) {
          if (tool === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             return;
          }

          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             draggingCompId.current = compId;
             dragOffset.current = { x: p.mouseX - comp.x, y: p.mouseY - comp.y };
          }
          return;
        }
      };

      p.mouseDragged = () => {
        if (draggingCompId.current) {
          isDraggingComp.current = true;
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp) {
            comp.x = Math.round((p.mouseX - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((p.mouseY - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
        }
      };

      p.mouseReleased = () => {
        if (draggingCompId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === draggingCompId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            comp.outputValues[0] = !comp.outputValues[0];
          }
        }

        draggingCompId.current = null;
        isDraggingComp.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(p.mouseX, p.mouseY);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);

    return () => {
      p5InstanceRef.current?.remove();
    };
  }, [tool, isPlaying, tickSpeedMs]);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
};

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas from './components/LogicCanvas';
import { ComponentType } from './types';
import { COMPONENT_DEFINITIONS } from './constants';

const App: React.FC = () => {
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(true);
  const [tickSpeed, setTickSpeed] = useState(200); // ms - Default to 200ms to visualize oscillation cleanly

  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number} | null>(null);

  const canvasWrapperRef = useRef<HTMLDivElement>(null);

  const handleTouchStartItem = (type: ComponentType, e: React.TouchEvent) => {
    const touch = e.touches[0];
    setDraggedType(type);
    setDragPos({ x: touch.clientX, y: touch.clientY });
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left &&
          dragPos.x <= rect.right &&
          dragPos.y >= rect.top &&
          dragPos.y <= rect.bottom
        ) {
          const relX = dragPos.x - rect.left;
          const relY = dragPos.y - rect.top;
          setPendingDrop({ type: draggedType, x: relX, y: relY });
        }
      }
      setDraggedType(null);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }

    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, dragPos]);

  const handlePendingDropHandled = () => {
    setPendingDrop(null);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={(t) => {
          if (t === 'SELECT' || t === 'DELETE') {
            setSelectedTool(t);
          }
        }}
        onTouchStartItem={handleTouchStartItem}
      />

      <main className="flex-1 flex flex-col relative">

        {/* Top Toolbar / HUD */}
        <div className="absolute top-4 left-4 right-4 h-14 bg-white/90 backdrop-blur shadow-sm rounded-lg flex items-center justify-between px-6 z-10 border border-slate-200 pointer-events-auto">
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2">
               <span className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></span>
               <span className="text-sm font-semibold text-slate-600">{isPlaying ? 'Running' : 'Paused'}</span>
             </div>

             <div className="h-6 w-px bg-slate-200 mx-2"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-3 py-1 bg-slate-100 hover:bg-slate-200 rounded text-sm font-medium transition-colors"
             >
               {isPlaying ? 'Pause' : 'Run'}
             </button>

             <button 
                onClick={() => window.location.reload()}
                className="px-3 py-1 text-red-500 hover:bg-red-50 rounded text-sm font-medium transition-colors"
              >
                Clear All
              </button>
          </div>

          <div className="flex items-center space-x-3">
            <span className="text-xs text-slate-400 font-medium uppercase">Delay (ms)</span>
            <input 
              type="range" 
              min="50" 
              max="1000" 
              step="50"
              value={tickSpeed} 
              onChange={(e) => setTickSpeed(Number(e.target.value))}
              className="w-32 accent-blue-600"
            />
            <span className="text-xs text-slate-500 w-12 text-right font-mono">{tickSpeed}ms</span>
          </div>
        </div>

        {/* Main Canvas Area */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            onPendingDropHandled={handlePendingDropHandled}
          />
        </div>

        {/* Ghost Element for Touch Dragging */}
        {draggedType && dragPos && (
          <div 
            className="fixed pointer-events-none z-50 opacity-80"
            style={{ 
              left: dragPos.x, 
              top: dragPos.y,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">
                {COMPONENT_DEFINITIONS[draggedType].label}
              </span>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

